// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.diimport com.roshan.persona.brain.agentic.AgenticExecutorimport com.roshan.persona.brain.agentic.AgenticOrchestratorimport com.roshan.persona.brain.agentic.AgenticPlannerimport com.roshan.persona.brain.agentic.ConstitutionalGuardrailsimport com.roshan.persona.brain.agentic.LlmAgenticPlannerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.intent.classifier.EmbedderInterfaceimport com.roshan.persona.brain.intent.classifier.TfIdfEmbedderimport com.roshan.persona.brain.intent.context.ContextualPreProcessorimport com.roshan.persona.brain.intent.slots.NerModelInterfaceimport com.roshan.persona.brain.llm.cache.SemanticLlmCacheimport com.roshan.persona.brain.llm.cache.InMemorySemanticLlmCacheimport com.roshan.persona.brain.llm.context.ContextInjectorimport com.roshan.persona.brain.llm.cost.LlmCostTrackerimport com.roshan.persona.brain.llm.guardrails.LocalLlmGuardrailsimport com.roshan.persona.brain.llm.layer.CloudLlmLayerimport com.roshan.persona.brain.llm.provider.CloudLlmProviderimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.llm.provider.LocalLlmProviderimport com.roshan.persona.brain.llm.registry.CloudProviderRegistryimport com.roshan.persona.brain.llm.registry.LocalLlmModelCatalogimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.rule.storage.ConversationStateStorageimport com.roshan.persona.brain.rule.storage.CrashSafeConversationStateStorageimport com.roshan.persona.brain.rule.storage.StateFileStorageimport com.roshan.persona.brain.skill.SkillDispatchersimport com.roshan.persona.brain.stream.StreamCoordinatorimport com.roshan.persona.common.AudioDispatcherimport com.roshan.persona.common.CvDispatcherimport com.roshan.persona.common.DefaultDispatcherimport com.roshan.persona.common.IoDispatcherimport com.roshan.persona.common.LlmDispatcherimport com.roshan.persona.common.Resultimport dagger.Bindsimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport kotlinx.coroutines.CoroutineDispatcherimport javax.inject.Singleton/** * NOUS — Brain Hilt Module (Integration-Complete v3). * * Wires ALL Brain dependencies into the Hilt graph: * *  - **Dispatchers** — bundled into [SkillDispatchers] (6 NOUS dispatchers). *  - **Interface bindings** (@Binds) for cache, storage, embedder, planner. *  - **@Provides** for classes with lambda params ([CloudLlmLayer], [LlmAgenticPlanner]). *  - **@Provides** for nullable interfaces ([LocalLlmProvider]?, [NerModelInterface]?). *  - **Real providers** for [CredentialVaultInterface] + [AuditLogPersistence] now live in *    :feature:security's SecurityModule (Strategy §12 Module 12). * * Strategy §14.2 Table 10 — Brain interface overrides: *   FakePermissionChecker       → RealPermissionChecker (:feature:security) ✅ *   FakeSystemOperationExecutor → SystemOperationExecutorImpl (:feature:system) ✅ *   NoOpCredentialVault         → CredentialVaultImpl (:feature:security) ✅ *   NoOpAuditLogPersistence     → EncryptedAuditLogPersistence (:feature:security) ✅ *   FakeEmbedder                → here (TfIdfEmbedder, real TFLite in Module 6) *   null NerModel               → here (null, real BERT-tiny in Module 6) * * @see <a href="docs/strategy/NOUS-Module-Strategy-2-14-extracted.txt">§14.2 Brain Interface Override Pattern</a> */@Module@InstallIn(SingletonComponent::class)object BrainModule {    // ─── Dispatchers ─────────────────────────────────────────────────────    @Provides    @Singleton    fun provideSkillDispatchers(        @IoDispatcher io: CoroutineDispatcher,        @DefaultDispatcher default: CoroutineDispatcher,        @LlmDispatcher llm: CoroutineDispatcher,        @CvDispatcher cv: CoroutineDispatcher,        @AudioDispatcher audio: CoroutineDispatcher,    ): SkillDispatchers = SkillDispatchers(        io = io,        default = default,        llm = llm,        cv = cv,        audio = audio,    )    // ─── LocalLlmProvider — PROVIDED BY :feature:llm's LlmModule ──────────    // Strategy §14.2: Brain interface override pattern.    // :feature:llm provides real LocalLlmProvider via LocalModelManager.    // When no model is loaded, it returns NoOpLocalLlmProvider (isLoaded=false).    // Brain does NOT provide this — avoids Hilt duplicate binding.    // ─── CloudLlmLayer — PROVIDED BY :feature:llm's LlmModule ─────────────    // Strategy §14.2: :feature:llm provides real CloudLlmLayer with    // CloudProviderFactory (not a throwing stub). Brain does NOT provide this.    // ─── LlmAgenticPlanner — PROVIDED BY :feature:llm's LlmModule ─────────    // Strategy §14.2: :feature:llm wires LlmAgenticPlanner to HybridLlmRouter.    // Brain does NOT provide this.    // ─── EmbedderInterface — PROVIDED BY :feature:vision's VisionModule ───    // Strategy §14.2 Table 10: OmniSlmEmbedder replaces TfIdfEmbedder.    // VisionModule provides real 384-dim semantic embeddings via Omni-SLM.    // Brain does NOT provide this — avoids Hilt duplicate binding.    // ─── NerModelInterface — PROVIDED BY :feature:vision's VisionModule ───    // Strategy §14.2 Table 10: OmniSlmNerModel replaces null NER.    // VisionModule provides real PERSON/ORG/LOCATION extraction.    // Brain does NOT provide this — avoids Hilt duplicate binding.    // ─── StateFileStorage — PROVIDED BY :feature:memory's MemoryModule ────    // Strategy §14.2: :feature:memory provides Room-backed StateFileStorage.    // Brain does NOT provide this — avoids Hilt duplicate binding.    // ─── CredentialVault — PROVIDED BY :feature:security's SecurityModule ──    // Strategy §12.4 + §14.2 Table 10: Module 12 (Security) now provides the    // real CredentialVaultImpl (backed by AndroidKeystore + EncryptedSharedPreferences).    // Brain does NOT provide this — avoids Hilt duplicate binding.    //    // The previous InMemoryCredentialVault stub has been REMOVED — it was    // lost on process death and had no encryption, suitable for dev only.    // ─── TtsBridge — PROVIDED BY :feature:voice's VoiceModule ─────────────    // Strategy §5.4: :feature:voice provides real AndroidTtsEngine.    // Brain does NOT provide this — avoids Hilt duplicate binding.    // ─── AuditLogPersistence — PROVIDED BY :feature:security's SecurityModule ─    // Strategy §12.4: Module 12 (Security) provides real EncryptedAuditLogPersistence    // (writes BrainTrace entries to EncryptedSharedPreferences with double-layer    // encryption). Brain does NOT provide this — avoids Hilt duplicate binding.    //    // The previous NoOpAuditLogPersistence stub has been REMOVED — it dropped    // audit logs on the floor, violating Strategy §8.1's 90-day retention rule.    // ─── LlmCaller — PROVIDED BY :feature:llm's LlmModule ────────────────    // Strategy §2.3.6: :feature:llm wires LlmCaller to HybridLlmRouter.    // Brain does NOT provide this.    // ─── AgenticToolRegistry (empty until modules register tools via Hilt multibinding) ─    @Provides    @Singleton    fun provideAgenticToolRegistry(        tools: Set<@JvmSuppressWildcards com.roshan.persona.brain.agentic.AgenticTool>,        memoryInterface: com.roshan.persona.brain.memory.MemoryInterface,    ): com.roshan.persona.brain.agentic.AgenticToolRegistry {        val registry = com.roshan.persona.brain.agentic.AgenticToolRegistry()        // Register built-in tools (RecallMemory, Calculate — always available, offline).        registry.registerAll(com.roshan.persona.brain.agentic.BuiltInAgenticTools.ALL(memoryInterface))        // Register tools from feature modules (WebSearchTool, FetchUrlTool from :feature:connectivity).        registry.registerAll(tools)        return registry    }}/** * Binds module for Brain's interface → impl mappings. * * Each @Binds here corresponds to a Strategy §14.2 Brain interface override. * Real implementations from feature modules will replace these bindings * when they ship their own @Module @InstallIn(SingletonComponent::class). */@Module@InstallIn(SingletonComponent::class)abstract class BrainBindingsModule {    @Binds    @Singleton    abstract fun bindSemanticLlmCache(impl: InMemorySemanticLlmCache): SemanticLlmCache    @Binds    @Singleton    abstract fun bindConversationStateStorage(        impl: CrashSafeConversationStateStorage,    ): ConversationStateStorage    @Binds    @Singleton    abstract fun bindAgenticPlanner(impl: LlmAgenticPlanner): AgenticPlanner}/** * NOUS — Provides classes whose constructors previously had default arguments. * * Kotlin generates two constructors when a class has `@Inject constructor(x: T = default)`: *   1. The primary: `constructor(x: T)` *   2. A synthetic no-arg: `constructor()` that calls primary with defaults * * Hilt sees both as @Inject-annotated and refuses to compile (DuplicateConstructors). * The fix: remove the defaults from the class, and provide the instances here * with explicit values. This module is the single source of truth for these * configuration values. */@Module@InstallIn(SingletonComponent::class)object BrainDefaultsModule {    @Provides    @Singleton    fun provideConstitutionalGuardrails(): com.roshan.persona.brain.agentic.ConstitutionalGuardrails =        com.roshan.persona.brain.agentic.ConstitutionalGuardrails(            additionalDangerousToolIds = emptySet(),        )    @Provides    @Singleton    fun provideAgenticCritic(        guardrails: com.roshan.persona.brain.agentic.ConstitutionalGuardrails,    ): com.roshan.persona.brain.agentic.AgenticCritic =        com.roshan.persona.brain.agentic.AgenticCritic(            maxRetriesPerStep = com.roshan.persona.brain.agentic.AgenticCritic.DEFAULT_MAX_RETRIES_PER_STEP,            constitutionalGuardrails = guardrails,        )    @Provides    @Singleton    fun provideSlotFiller(        nerModel: com.roshan.persona.brain.intent.slots.NerModelInterface?,    ): com.roshan.persona.brain.intent.slots.SlotFiller =        com.roshan.persona.brain.intent.slots.SlotFiller(nerModel = nerModel)    @Provides    @Singleton    fun provideInMemorySemanticLlmCache(): com.roshan.persona.brain.llm.cache.InMemorySemanticLlmCache =        com.roshan.persona.brain.llm.cache.InMemorySemanticLlmCache(            similarityThreshold = 0.95f,            maxEntries = 1000,            ttlDays = 30L,            volatileTtlMinutes = 5L,        )    @Provides    @Singleton    fun provideLlmCostTracker(): com.roshan.persona.brain.llm.cost.LlmCostTracker =        com.roshan.persona.brain.llm.cost.LlmCostTracker(            userTimezone = java.time.ZoneId.systemDefault(),        )    @Provides    @Singleton    fun provideStreamCoordinator(        ttsBridge: com.roshan.persona.brain.stream.TtsBridge?,    ): com.roshan.persona.brain.stream.StreamCoordinator =        com.roshan.persona.brain.stream.StreamCoordinator(ttsBridge = ttsBridge)    @Provides    @Singleton    fun provideBrainTracePolicy(): com.roshan.persona.brain.orchestrator.BrainTracePolicy =        com.roshan.persona.brain.orchestrator.BrainTracePolicy(            maxCachedTraces = 1_000,            retentionDays = com.roshan.persona.brain.orchestrator.BrainTracePolicy.DEFAULT_RETENTION_DAYS,        )    @Provides    @Singleton    fun provideBrainPreProcessor(        memoryInterface: com.roshan.persona.brain.memory.MemoryInterface?,        constitutionalGuardrails: com.roshan.persona.brain.agentic.ConstitutionalGuardrails,        contextInjector: com.roshan.persona.brain.llm.context.ContextInjector?,    ): com.roshan.persona.brain.orchestrator.BrainPreProcessor =        com.roshan.persona.brain.orchestrator.BrainPreProcessor(            memoryInterface = memoryInterface,            constitutionalGuardrails = constitutionalGuardrails,            contextInjector = contextInjector,        )    @Provides    @Singleton    fun provideAgenticGuardrails(): com.roshan.persona.brain.agentic.AgenticGuardrails =        com.roshan.persona.brain.agentic.AgenticGuardrails()    @Provides    @Singleton    fun provideContextInjector(        memoryInterface: com.roshan.persona.brain.memory.MemoryInterface?,        skills: Set<@JvmSuppressWildcards com.roshan.persona.brain.skill.BrainSkill>,    ): com.roshan.persona.brain.llm.context.ContextInjector =        com.roshan.persona.brain.llm.context.ContextInjector(            memoryInterface = memoryInterface,            availableSkills = skills,            tokenEstimator = com.roshan.persona.brain.llm.context.ContextInjector.TokenEstimator { text ->                // Real token estimate: ~4 chars per token for English, ~2 chars for CJK.                // This is the standard heuristic used by tiktoken/transformers.                (text.length / 4).coerceAtLeast(1)            },        )    @Provides    @Singleton    fun provideLocalLlmGuardrails(): com.roshan.persona.brain.llm.guardrails.LocalLlmGuardrails =        com.roshan.persona.brain.llm.guardrails.LocalLlmGuardrails()    @Provides    @Singleton    fun provideLocalLlmLayer(        provider: com.roshan.persona.brain.llm.provider.LocalLlmProvider,        guardrails: com.roshan.persona.brain.llm.guardrails.LocalLlmGuardrails,        cache: com.roshan.persona.brain.llm.cache.SemanticLlmCache?,        contextInjector: com.roshan.persona.brain.llm.context.ContextInjector,        brainBus: com.roshan.persona.brain.bus.BrainBus,    ): com.roshan.persona.brain.llm.layer.LocalLlmLayer =        com.roshan.persona.brain.llm.layer.LocalLlmLayer(            provider = provider,            guardrails = guardrails,            cache = cache,            contextInjector = contextInjector,            brainBus = brainBus,            embeddingModelVersion = com.roshan.persona.brain.llm.layer.LocalLlmLayer.DEFAULT_EMBEDDING_VERSION,            lowConfidenceMinTokens = com.roshan.persona.brain.llm.layer.LocalLlmLayer.DEFAULT_LOW_CONFIDENCE_MIN_TOKENS,            lowConfidenceRepetitionThreshold = com.roshan.persona.brain.llm.layer.LocalLlmLayer.DEFAULT_REPETITION_THRESHOLD,        )}